(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7828],{67487:()=>{},80186:(e,t,a)=>{"use strict";a.d(t,{L:()=>c,PatchSeen:()=>d});var s=a(95155),o=a(98500),r=a.n(o),n=a(12115);let i="Extra projectiles now deal 35% to an enemy another projectile of the same attack already hit.",l=[{version:"1.2",date:"2026-09-27",headline:"Kitty joins: fighter 10 wins the horde over",summary:"Kitty, the comeback cat with the most fans, is fighter 10. Her hearts crush whatever they hit, and the third crush charms it: a charmed enemy fights on your side for a few seconds, and nothing your squad throws can hurt it. Bosses never fall for anyone, but a full crush leaves one smitten. She plays in every mode, co-op included.",general:[{label:"Charmed enemies",tag:"new",art:"kitty-disc.webp",text:"Kitty's fans hunt the horde near her and never touch a fighter. Everyone's shots fly through them, and the horde ignores them. A fan with nobody to fight gets bored and snaps out of it sooner, and for three seconds after that it cannot be charmed again."},{label:"Smitten bosses",tag:"new",symbol:"boss",text:"A boss cannot be charmed. Three crushes leave it smitten instead: for four seconds every fighter's hits on it land 25% harder."}],fighters:[{fighter:"kitty",tag:"new",note:'An idol who wins the horde over instead of wiping it out. Her kit comes from her token\'s own world: the pink bow logo, the pixel hearts and record player on its site, its "cutest takeover in crypto" line, and a comeback from almost nothing. In our test runs (a bot, 36 runs) she won every run, made the most Survival kills of the roster with random upgrades, and cleared District Run in 9:54 with stacked upgrades, next to Zcash and Ansem.',changes:[{label:"Heart Shot",skill:"primary",tag:"new",text:"A pixel heart for 18. Every heart that lands is a crush, and the third crush charms the enemy for five seconds (six and seven as she evolves). A heart that kills is a kill, not a charm."},{label:"Put a Bow on It",skill:"skill",tag:"new",text:"Toss your bow up to 330 away. It gift-wraps everything it lands on: held for two seconds, two crushes along, so one more heart charms it."},{label:"Drop the Needle",skill:"special",tag:"new",text:"A record player for six seconds. Every beat (120 a minute) hits the dance floor around it, every second beat is a crush, and fans on the floor hit twice as fast."},{label:"Cutest Takeover",skill:"ultimate",tag:"new",text:"Everything within 420 falls for her at once for seven seconds. A boss is starstruck for a second and smitten for the rest."},{label:"Comeback",upgrade:"regen",tag:"new",text:"Once per run, a hit that would take her down leaves her at half health, untouchable for two seconds, and charms everyone around her. A new District Run encounter does not bring it back."},{label:"Skip",skill:"dash",tag:"new",text:"The quick, untouchable dash every fighter has."}]}],modes:[{label:"Co-op",tag:"new",symbol:"squad",text:"Kitty plays in co-op: her fans fight for the whole squad, and a boss she has smitten takes more damage from everyone. This patch updates the co-op server too, so reload an open Meme Surge tab before you join a room."}],fixes:[]},{version:"1.1",date:"2026-09-24",headline:"Bosses fight back, aim assist, all nine fighters rebalanced",summary:"Stacked split upgrades could flatten a boss in one throw. Extra projectiles now lose most of their damage on a target the same attack already hit, a boss's guard needs sustained pressure to break, and Survival bosses grow with your level. Arrow keys no longer walk one way while your fighter faces the other, and without a mouse your attacks aim at the nearest enemy ahead.",general:[{label:"Split upgrades",upgrade:"spread",tag:"nerf",from:"100%",to:"35%",text:`${i} Against a crowd every projectile still hits for full. Covers Extra baggage, Pocket change, Second draft, Extra tube, Parallel jobs and Zcat's extra shots.`},{label:"Split limit",upgrade:"spread",tag:"adjust",from:"No limit",to:"6",text:"Every fighter can take six. Zcat and Ansem had no limit."},{label:"Boss guard",tag:"adjust",symbol:"guard",text:"One burst can no longer break a guard. Hits wear at most 40 guard at once, refilling at 26 a second, or 140 a second while the boss is EXPOSED. Keep the pressure on, or hit it while it is exposed."},{label:"Survival bosses (solo)",tag:"adjust",symbol:"boss",from:"1,100 / 2,200 / 4,600",to:"2,600 / 4,400 / 6,000",text:"Solo: the Collector, the Iron Bailiff and the Gatekeeper start tougher and gain 10% of that per level, as Road bosses already did. Co-op bosses keep their health and still scale with the size of the squad."},{label:"Aim assist",tag:"new",symbol:"aim",text:"When neither the mouse nor the aim stick is aiming, attacks and skills aim at the nearest enemy ahead of you, or where you walk when nothing is in reach. Move or click the mouse and it takes the aim back."}],fighters:[{fighter:"zcat",tag:"nerf",note:"Zcat cleared District Run and the Road faster than anyone. A little less plasma per shot.",changes:[{label:"Plasma Pistol",skill:"primary",tag:"nerf",text:"Damage per shot",from:"23",to:"20"},{label:"Extra shots",upgrade:"spread",tag:"nerf",text:`Now limited to six. ${i}`}]},{fighter:"ansem",tag:"buff",note:"Ansem almost never took damage in our test runs but was the slowest to clear District Run. More damage, reach and a quicker charge help him get to the fight.",changes:[{label:"Horn Cleave",skill:"primary",tag:"buff",text:"Damage",from:"34",to:"44"},{label:"Horn Cleave",skill:"primary",tag:"buff",text:"Swing time",from:"0.50 s",to:"0.46 s"},{label:"Horn Cleave",skill:"primary",tag:"buff",text:"Reach",from:"108",to:"116"},{label:"Bull Rush",skill:"skill",tag:"buff",text:"Cooldown",from:"8 s",to:"6.5 s"},{label:"Movement speed",tag:"buff",upgrade:"speed",from:"192",to:"200"}]},{fighter:"cate",tag:"nerf",note:"Cate's coins cleared District Run almost as fast as Zcat.",changes:[{label:"Coin Toss",skill:"primary",tag:"nerf",text:"Damage per coin",from:"31",to:"29"},{label:"Pocket change",upgrade:"spread",tag:"nerf",text:i}]},{fighter:"useless",tag:"adjust",note:"Seven full-damage scrap pieces could land on one boss at once: a stacked Useless broke a boss's guard with its first throw and finished it with the second. That build now follows the split rule, and the base throw and legs get stronger to make up for it.",changes:[{label:"Extra baggage",upgrade:"spread",tag:"nerf",text:`Seven pieces on one boss: seven full hits before, one full hit and six at 35% now. ${i}`},{label:"Paperweight",skill:"primary",tag:"buff",text:"Damage",from:"58",to:"66"},{label:"Movement speed",tag:"buff",upgrade:"speed",from:"182",to:"190"}]},{fighter:"zcash",tag:"buff",note:"Zcash and Ansem were the slowest to finish District Run, and Zcash's last boss took over a minute. Its daggers hit harder and reach further, and Zero Knowledge now spends every strike.",changes:[{label:"Twin Proofs",skill:"primary",tag:"buff",text:"Damage per slash",from:"22",to:"30"},{label:"Twin Proofs",skill:"primary",tag:"buff",text:"Reach",from:"82",to:"90"},{label:"Zero Knowledge",skill:"ultimate",tag:"buff",text:"Always makes all of its strikes (8, then 10 and 12 as Zcash evolves). With fewer enemies in reach it goes round them again, so a lone boss takes every strike."},{label:"Health",tag:"buff",upgrade:"vitality",from:"105",to:"110"}]},{fighter:"doublezero",tag:"buff",note:"The lash chains through a crowd well, but a boss is one target: District Run bosses took DoubleZero three to four times as long as Zcat, Cate or MarsCoin.",changes:[{label:"Packet Lash",skill:"primary",tag:"buff",text:"Damage to the first target",from:"26",to:"29"}]},{fighter:"pons",tag:"adjust",note:"Second draft follows the split rule, so the bolt itself hits a little harder.",changes:[{label:"Second draft",upgrade:"spread",tag:"nerf",text:i},{label:"Quill Bolt",skill:"primary",tag:"buff",text:"Damage",from:"24",to:"26"}]},{fighter:"marscoin",tag:"adjust",note:"Only the split rule. MarsCoin stays in the middle of the pack.",changes:[{label:"Extra tube",upgrade:"spread",tag:"nerf",text:i}]},{fighter:"virtuals",tag:"adjust",note:"Only the split rule. The agents carry Virtuals Protocol's damage and are unchanged.",changes:[{label:"Parallel jobs",upgrade:"spread",tag:"nerf",text:i}]}],modes:[{label:"Choose your arena",tag:"new",symbol:"arena",text:"The lobby has a second step: pick District Run, Survival or The Road from full-size paintings. Swipe, use the arrow keys, or tap a tab."},{label:"District Run: eighteen encounters",tag:"new",symbol:"district",text:"Three districts of six encounters each: a breach, a supply raid, a relay hold (stand in the ring until it charges), an ambush, a bounty elite and the district's boss. Bosses call reinforcements at half health, and each new district restores 40% of your health."},{label:"District Run saves",tag:"new",symbol:"save",text:"The run saves after every encounter. Quit whenever you like and continue later from the fighter screen. Signed-in players can continue on another device."}],benchmark:{method:"A test bot played every fighter six times in each mode, once stacking the same upgrade and once picking at random: 324 runs on the old version and 324 on this one. The table shows medians with stacked upgrades; boss time counts from the first hit.",rows:[{fighter:"zcat",district:["7:51","7:55"],boss:[.6,5.1]},{fighter:"ansem",district:["11:40","10:52"],boss:[3.1,9.7]},{fighter:"cate",district:["7:54","8:04"],boss:[.6,4.1]},{fighter:"useless",district:["8:13","8:43"],boss:[.8,7.6]},{fighter:"zcash",district:["11:37","9:36"],boss:[2.1,7.8]},{fighter:"doublezero",district:["8:48","8:34"],boss:[2.2,9]},{fighter:"pons",district:["8:19","8:30"],boss:[1.2,8.6]},{fighter:"marscoin",district:["7:56","8:18"],boss:[.9,5.9]},{fighter:"virtuals",district:["8:04","8:17"],boss:[1.1,9.7]}],totals:["Survival bosses now last 9.1 s after the first hit, up from 1.6 s. Before, 62% of them went down in under two seconds; now none do.","Fastest to slowest District Run clear: 7:51 to 11:40 before, 7:55 to 10:52 now.","The bot won 324 of 324 runs (323 before)."]},fixes:[{label:"Arrow keys",tag:"fix",symbol:"keys",text:"Once the mouse had touched the arena, the fighter kept facing and firing at the resting cursor, so holding → could walk right while facing left. The mouse now aims only while you use it, and a fighter faces the way it walks unless it is attacking."},{label:"Result screen",tag:"fix",symbol:"scroll",text:"A long result (a Road clear with relics and trophies) showed a white scrollbar inside the panel and cut it off. Now the whole screen scrolls and the panel shows in full."},{label:"Co-op",tag:"fix",symbol:"squad",text:"Teammates now face the same way on every screen: toward their aim while attacking, the way they walk otherwise."}]}][0],h="meme-surge-patch-seen";function d({version:e}){return(0,n.useEffect)(()=>{try{localStorage.setItem(h,e)}catch{}},[e]),null}function c({className:e}){let[t,a]=(0,n.useState)(!1);return(0,n.useEffect)(()=>{a(function(){try{return localStorage.getItem(h)}catch{return null}}()!==l.version)},[]),(0,s.jsxs)(r(),{href:"/meme-surge/patch-notes",className:e??"ms-patch-link","aria-label":`Patch ${l.version} notes${t?", new":""}`,children:["Patch ",l.version,t?(0,s.jsx)("b",{children:"New"}):null]})}}}]);